<script module lang="ts">
    export const layout = { breadcrumbs: [{ title: 'Maintenance', href: '/owner/maintenance' }, { title: 'Detail pekerjaan', href: '#' }] };
</script>

<script lang="ts">
    import { Form, Link } from '@inertiajs/svelte';
    import AppHead from '@/components/AppHead.svelte';
    import InputError from '@/components/InputError.svelte';
    import { Button } from '@/components/ui/button';
    import { Input } from '@/components/ui/input';

    type Job = { id: number; status: string; category: string; description: string; blocks_room: boolean; scheduled_start_date: string | null; scheduled_end_exclusive: string | null; room: { id: number; code: string } | null; property: { id: number; name: string }; vendor_name: string | null; completed_at: string | null; created_at: string };
    let { job }: { job: Job } = $props();
    const labels: Record<string, string> = { reported: 'Dilaporkan', scheduled: 'Dijadwalkan', completed: 'Selesai', cancelled: 'Dibatalkan' };
</script>

<AppHead title={`Maintenance ${job.id}`} />
<main class="mx-auto w-full max-w-4xl space-y-6 p-4 md:p-8">
    <header class="flex flex-wrap items-start justify-between gap-4"><div class="space-y-2"><p class="text-sm font-medium text-muted-foreground">{job.property.name}{job.room ? ` · Kamar ${job.room.code}` : ' · Fasilitas umum'}</p><h1 class="text-3xl font-semibold tracking-tight">{job.category}</h1><p class="text-sm text-muted-foreground">Status: {labels[job.status] ?? job.status}</p></div><Link href="/owner/maintenance" class="inline-flex items-center rounded-md border px-4 py-2 text-sm">Daftar maintenance</Link></header>
    <section class="grid gap-4 sm:grid-cols-2"><article class="rounded-xl border bg-card p-5 shadow-sm"><h2 class="font-semibold">Deskripsi</h2><p class="mt-2 whitespace-pre-wrap text-sm text-muted-foreground">{job.description}</p></article><article class="rounded-xl border bg-card p-5 shadow-sm"><h2 class="font-semibold">Rincian</h2><dl class="mt-3 space-y-2 text-sm"><div class="flex justify-between gap-3"><dt class="text-muted-foreground">Status</dt><dd>{labels[job.status] ?? job.status}</dd></div><div class="flex justify-between gap-3"><dt class="text-muted-foreground">Kamar diblokir</dt><dd>{job.blocks_room ? 'Ya' : 'Tidak'}</dd></div><div class="flex justify-between gap-3"><dt class="text-muted-foreground">Vendor</dt><dd>{job.vendor_name || '—'}</dd></div><div class="flex justify-between gap-3"><dt class="text-muted-foreground">Dilaporkan</dt><dd>{new Intl.DateTimeFormat('id-ID', { dateStyle: 'medium', timeZone: 'Asia/Jakarta' }).format(new Date(job.created_at))}</dd></div></dl></article></section>
    <section class="rounded-xl border bg-card p-5 shadow-sm"><h2 class="font-semibold">Jadwal</h2>{#if job.scheduled_start_date && job.scheduled_end_exclusive}<p class="mt-2">{job.scheduled_start_date} – {job.scheduled_end_exclusive}</p><p class="mt-1 text-sm text-muted-foreground">Kamar tersedia kembali pada tanggal akhir.</p>{:else}<p class="mt-2 text-sm text-muted-foreground">Belum ada jadwal maintenance.</p>{/if}{#if job.completed_at}<p class="mt-2 text-sm text-muted-foreground">Selesai pada {job.completed_at}</p>{/if}</section>
    {#if job.status === 'reported' || job.status === 'scheduled'}<section class="space-y-4"><h2 class="text-lg font-semibold">Tindakan pekerjaan</h2>
        {#if job.status === 'reported'}<Form action={`/owner/maintenance/${job.id}/schedule`} method="post" class="space-y-4 rounded-xl border bg-card p-5 shadow-sm">{#snippet children({ errors, processing })}<div><h3 class="font-medium">Jadwalkan pekerjaan</h3><p class="text-sm text-muted-foreground">Jadwal yang memblokir kamar ditolak bila bertabrakan dengan booking confirmed atau tenancy scheduled/active.</p></div><div class="grid gap-4 sm:grid-cols-2"><div class="space-y-2"><label for="scheduled_start_date" class="text-sm font-medium">Mulai</label><Input id="scheduled_start_date" name="scheduled_start_date" type="date" required /><InputError message={errors.scheduled_start_date} /></div><div class="space-y-2"><label for="scheduled_end_exclusive" class="text-sm font-medium">Kamar tersedia kembali mulai</label><Input id="scheduled_end_exclusive" name="scheduled_end_exclusive" type="date" required /><p class="text-xs text-muted-foreground">Batas akhir tidak termasuk.</p><InputError message={errors.scheduled_end_exclusive} /></div></div><label class="flex items-start gap-2 text-sm"><input type="checkbox" name="blocks_room" value="1" checked={job.blocks_room} class="mt-0.5 size-4 rounded border" /><span>Kamar tidak dapat digunakan selama jadwal ini</span></label><InputError message={errors.maintenance} /><div class="flex justify-end"><Button type="submit" disabled={processing}>{processing ? 'Memeriksa…' : 'Simpan jadwal'}</Button></div>{/snippet}</Form>{/if}
        {#if job.status === 'scheduled'}<Form action={`/owner/maintenance/${job.id}/complete`} method="post" class="space-y-3 rounded-xl border bg-card p-5 shadow-sm">{#snippet children({ errors, processing })}<div><h3 class="font-medium">Tandai selesai</h3><p class="text-sm text-muted-foreground">Pekerjaan selesai tidak lagi memblokir kamar. Pembayaran biaya dicatat di alur keuangan.</p></div><label class="flex items-start gap-2 text-sm"><input type="checkbox" name="confirmation" value="1" required class="mt-0.5 size-4 rounded border" /><span>Saya mengonfirmasi pekerjaan telah selesai.</span></label><InputError message={errors.maintenance} /><div class="flex justify-end"><Button type="submit" variant="outline" disabled={processing}>{processing ? 'Menyimpan…' : 'Tandai selesai'}</Button></div>{/snippet}</Form>{/if}
        {#if job.status === 'scheduled'}<Form action={`/owner/maintenance/${job.id}/cancel`} method="post" class="space-y-3 rounded-xl border border-amber-300/60 bg-card p-5 shadow-sm">{#snippet children({ errors, processing })}<div><h3 class="font-medium">Batalkan jadwal</h3><p class="text-sm text-muted-foreground">Jadwal yang dibatalkan tidak lagi menahan ketersediaan kamar.</p></div><div class="space-y-2"><label for="cancel_reason" class="text-sm font-medium">Alasan</label><textarea id="cancel_reason" name="reason" rows={2} required maxlength={500} class="w-full rounded-md border bg-background px-3 py-2 text-sm"></textarea><InputError message={errors.reason} /></div><label class="flex items-start gap-2 text-sm"><input type="checkbox" name="confirmation" value="1" required class="mt-0.5 size-4 rounded border" /><span>Saya memahami jadwal ini akan dibatalkan.</span></label><div class="flex justify-end"><Button type="submit" variant="destructive" disabled={processing}>{processing ? 'Membatalkan…' : 'Batalkan jadwal'}</Button></div>{/snippet}</Form>{/if}
    </section>{/if}
</main>
